/// url = 'http://octofhir.com/ccda-fhir/StructureMap/cda-problems-to-fhir'
/// name = 'CdaProblemsToFhir'
/// title = 'C-CDA problems to US Core Condition'
/// status = 'active'
/// description = 'Problem Concern acts to US Core 6.1.0 Condition (Problems and Health Concerns), after "Problems CDA → FHIR" of C-CDA on FHIR 2.0.0: each Problem observation is one Condition.'

map "http://octofhir.com/ccda-fhir/StructureMap/cda-problems-to-fhir" = "CdaProblemsToFhir"

uses "http://hl7.org/cda/stds/core/StructureDefinition/Section" alias Section as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/ProblemConcernAct" alias ProblemConcernAct as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/ProblemObservation" alias ProblemObservation as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/ProblemStatus" alias ProblemStatus as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/DateOfDiagnosisAct" alias DateOfDiagnosisAct as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/AgeObservation" alias AgeObservation as source
uses "http://hl7.org/cda/us/ccda/StructureDefinition/CommentActivity" alias CommentActivity as source
uses "http://hl7.org/fhir/StructureDefinition/Condition" alias Condition as target
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as target

imports "http://octofhir.com/ccda-fhir/StructureMap/cda-datatypes-to-fhir"
imports "http://octofhir.com/ccda-fhir/StructureMap/cda-participants-to-fhir"

// A problem section (or any section holding Problem Concern acts): its LOINC code gives the
// category of every Condition in it.
group ProblemSection(source section : Section, target compositionSection, target bundle : Bundle, source patientId : string) {
  section.entry as entry then {
    entry.act : ProblemConcernAct as act then {
      act.entryRelationship as relationship then {
        relationship.observation : ProblemObservation as observation -> bundle.entry as resourceEntry, resourceEntry.resource = create('Condition') as condition, uuid() as id, condition.id = id, resourceEntry.fullUrl = append('urn:uuid:', id), compositionSection.entry as ref, ref.reference = append('urn:uuid:', id), condition.subject as subject, subject.reference = append('urn:uuid:', patientId) then Condition(section, act, observation, condition, bundle);
      };
    };
  };
}

group Condition(source section : Section, source act : ProblemConcernAct, source observation : ProblemObservation, target condition : Condition, target bundle : Bundle) {
  observation -> condition.meta as meta, meta.profile = 'http://hl7.org/fhir/us/core/StructureDefinition/us-core-condition-problems-health-concerns';
  observation.id as id -> condition.identifier as i then IIToIdentifier(id, i);
  // Category: from the section's code; a problem list item when that says nothing.
  section.code as code then {
    code.code as c where (c in ('11450-4' | '46240-8' | '75310-3')) -> condition.category as category, category.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-category', coding.code = translate(c, 'http://hl7.org/fhir/us/ccda/ConceptMap/CF-ProblemCategory', 'code');
  };
  section where (code.code.where($this in ('11450-4' | '46240-8' | '75310-3')).empty()) -> condition.category as category, category.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-category', coding.code = 'problem-list-item';
  // The observation's code (a problem type) as a second category.
  observation.code as code where (code.exists()) -> condition.category as category then CDToCodeableConcept(code, category);
  // Clinical status: the Problem Status observation, else the concern's statusCode.
  observation.entryRelationship as relationship then {
    relationship.observation : ProblemStatus as status then {
      status.value as value then {
        value.code as code -> condition.clinicalStatus as cs, cs.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical', coding.code = translate(code, 'http://hl7.org/fhir/us/ccda/ConceptMap/CF-ProblemStatus', 'code');
      };
    };
  };
  act.statusCode as statusCode where (%observation.entryRelationship.observation.where(hasTemplateIdOf('urn:oid:2.16.840.1.113883.10.20.22.4.6')).empty() and %observation.effectiveTime.high.empty()) then {
    statusCode.code as code -> condition.clinicalStatus as cs, cs.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical', coding.code = translate(code, 'http://hl7.org/fhir/us/ccda/ConceptMap/CF-ConditionClinicalStatus', 'code');
  };
  // An end (or an unknown end) means the problem is no longer active.
  observation.effectiveTime as time where (high.exists() and %observation.entryRelationship.observation.where(hasTemplateIdOf('urn:oid:2.16.840.1.113883.10.20.22.4.6')).empty()) -> condition.clinicalStatus as cs, cs.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-clinical', coding.code = 'resolved';
  observation where (negationInd = true) -> condition.verificationStatus as vs, vs.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-ver-status', coding.code = 'refuted';
  observation where (negationInd.exists().not() or negationInd = false) -> condition.verificationStatus as vs, vs.coding as coding, coding.system = 'http://terminology.hl7.org/CodeSystem/condition-ver-status', coding.code = 'confirmed';
  observation.value as value -> condition.code as code then CDToCodeableConcept(value, code);
  observation.effectiveTime as time then {
    time.low as low where (value.exists()) -> condition.onset = create('dateTime') as onset then TSToDateTime(low, onset);
    time.value as v where (%time.low.empty()) -> condition.onset = create('dateTime') as onset then TSToDateTime(time, onset);
    time.high as high where (value.exists()) -> condition.abatement = create('dateTime') as abatement then TSToDateTime(high, abatement);
  };
  observation.author last as author -> condition.recorder as ref then AuthorReference(author, ref, bundle);
  observation where (author.empty()) then {
    act.author last as author -> condition.recorder as ref then AuthorReference(author, ref, bundle);
  };
  observation.author first as author then {
    author.time as time -> condition.recordedDate = create('dateTime') as date then TSToDateTime(time, date);
  };
  observation.entryRelationship as relationship then {
    relationship.act : DateOfDiagnosisAct as diagnosis then {
      diagnosis.effectiveTime as time then {
        time.value as v -> condition.extension as ext, ext.url = 'http://hl7.org/fhir/StructureDefinition/condition-assertedDate', ext.value = create('dateTime') as date then TSToDateTime(time, date);
      };
    };
    relationship.observation : AgeObservation as age where (%observation.effectiveTime.low.value.empty()) then {
      age.value as value -> condition.onset = create('Age') as onset then PQToQuantity(value, onset);
    };
    relationship.act : CommentActivity as comment -> condition.note as note then CommentToAnnotation(comment, note);
  };
}
